<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($ticket['ticket_number'])?></title><link rel="stylesheet" href="/assets/app.css"><style><?=theme_css_vars()?></style></head><body class="auto-print"><main class="ticket"><h2><?=e(app_name())?></h2><p><?=e($ticket['service_name'])?></p><strong><?=e($ticket['ticket_number'])?></strong><p><?=e(date('d/m/Y H:i',strtotime($ticket['created_at'])))?></p><hr><p>Mohon menunggu nomor Anda dipanggil.</p></main><div class="printing-message">Printing queue ticket…</div><script>addEventListener('afterprint',()=>location.replace('/kiosk'));addEventListener('load',()=>setTimeout(()=>print(),150));setTimeout(()=>location.replace('/kiosk'),15000);</script></body></html>
